const updateDateTimeDOM = () => {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  const hours = String(now.getHours()).padStart(2, '0');
  const minutes = String(now.getMinutes()).padStart(2, '0');
  const seconds = String(now.getSeconds()).padStart(2, '0');

  // 更新日期显示
  const dateItems = document.querySelectorAll('.dateBox .item')[0]?.querySelectorAll('span');
  if (dateItems && dateItems.length >= 8) {
    const fullDate = `${year}${month}${day}`.split('');
    for (let i = 0; i < 8; i++) {
      if (fullDate[i]) {
        dateItems[i].textContent = fullDate[i];
      }
    }
  }

  // 更新时间显示
  const timeItems = document.querySelectorAll('.dateBox .item')[1]?.querySelectorAll('span');
  if (timeItems && timeItems.length >= 6) {
    const fullTime = `${hours}${minutes}${seconds}`.split('');
    for (let i = 0; i < 6; i++) {
      if (fullTime[i]) {
        timeItems[i].textContent = fullTime[i];
      }
    }
  }
};

// 启动定时更新

